So `useCertificados` needs a refetch. Let me check the actual `useCertificados.ts` file content (via git show, the active/production one I trust). I saw it earlier (43 lines). Let me get the exact content to edit it precisely. Actually I already have it from the earlier bash git show:

```
import { useState, useEffect } from 'react';
import { Certificado } from '../api/types';
import { api } from '../api/client';

export function useCertificados(apiClient = api) {
  const [certificados, setCertificados] = useState<Certificado[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);

  useEffect(() => {
    let isMounted = true;
    setLoading(true);
    setError(null workspace

    apiClient
      .getCertificados()
      .then((res) => {
        if (isMounted) {
          setCertificados(res);
          setLoading(false);
        }
      })
      .catch((err: any) => {
        if (isMounted) {
          setError({ erro: ..., mensagem: ... });
          setLoading(false);
        }
      });

    return () => {
      isMounted = false;
    };
  }, [apiClient]);

  return { certificados, loading, error };
}
```

